import {canBid} from './engine.js';
import {joinQR} from './join-qr.js';
import {jokerButton} from './joker-ui.js';
export function createTVUI({esc,photo,cardInfo,timerUI,seriesUI}){
 const stars=deal=>deal?`<span class="tv-deal" aria-label="F/P ${deal.stars}/5">F/P <b>${'★'.repeat(deal.stars)}${'☆'.repeat(5-deal.stars)}</b> · ${esc(deal.label)}</span>`:'';
 function controller(g,{you,busy,connectionError,cap}){
  const me=g.players.find(p=>p.id===you),person=g.players.find(p=>p.id===g.turnId),mine=canBid(g,you),sold=g.status==='sold',countdown=g.status==='countdown',deal=sold&&g.settings.pricePerformance?g.lastSale?.card.deal:null;
  const status=countdown?`<div class="remote-countdown"><span>Sıradaki kart geliyor</span><strong data-reveal-number>3</strong><small>Televizyona bak 👀</small></div>`:sold?`<div class="remote-sale"><strong>${esc(g.lastSale.name)} aldı!</strong><span>${g.lastSale.card.paid} jetona · ${g.lastSale.remainingBudget} jetonu kaldı</span>${stars(deal)}<small>Yeni kart otomatik açılacak <b data-next-number></b></small></div>`:`<div class="remote-turn"><span>${g.price===0?'İlk teklif sırası':g.leaderId===you?'Teklifin önde':mine?'Sıra beklemeden artır':'Bu kartta teklif veremiyorsun'}</span><strong>${g.price===0?esc(person?.name):mine?'Artıran var mı?':esc(g.players.find(p=>p.id===g.leaderId)?.name)+' önde'}</strong><small>${esc(g.current.name)} · ${g.price||1} jeton</small></div>${timerUI(g)}`;
  return `<section class="tv-controller"><div class="remote-identity"><span><small>TV kumandan</small><strong>${esc(me.name)}</strong></span><div><strong>${me.budget}</strong><small>jetonun kaldı</small></div></div><div class="remote-status ${sold?'sold':''}" role="status">${status}</div><button class="remote-bid ${mine?'ready':''}" data-action="bid" data-amount="${g.price+1}" ${!mine||busy||connectionError||g.price+1>cap?'disabled':''}><small>${mine?'Teklif ver':sold?'Kart satıldı':countdown?'Hazırlan':me.cards.length===g.settings.slots?'Kadron tamam':g.leaderId===you?'Şu an öndesin':g.price===0?'Açılışı bekle':'Bu kartta yoksun'}</small><strong>${mine?g.price===0?'1 jeton':'+1 jeton':'● ● ●'}</strong><span>${mine?g.price===0?'Açık artırmayı başlat':`Yeni teklifin ${g.price+1} jeton`:g.price===0?'İlk tekliften sonra herkes artırabilir':g.leaderId===you?'Başka biri artırırsa düğmen açılır':'Sonraki kartta yeniden katıl'}</span></button>${jokerButton(g,me,{mine,busy,connectionError,className:'remote-pass'})||`<button class="btn ghost remote-pass" data-action="pass" ${!mine||g.price===0||busy||connectionError?'disabled':''}>Bu karttan çekil</button>`}<section class="remote-roster"><header><h2>Benim kadrom</h2><span>${me.cards.length} / ${g.settings.slots}${g.settings.jokers?' · '+(me.jokersLeft||0)+' joker':''}</span></header><div class="remote-roster-list">${me.cards.length?me.cards.map(card=>`<article>${photo(card,'remote-card-photo')}<span><strong>${esc(card.name)}</strong>${g.settings.pricePerformance?stars(card.deal):''}</span><b>${card.paid} j</b></article>`).join(''):'<p>İlk kartını alınca burada göreceksin.</p>'}</div></section><button class="remote-details" data-action="table-details">Kart bilgisi ve tüm kadrolar ↗</button></section>`;
 }
 function players(g){return `<div class="tv-players">${g.players.map(p=>`<div class="tv-player ${p.id===g.turnId?'current':''} ${p.id===g.leaderId?'leading':''}"><span class="tv-avatar">${esc(p.name[0])}</span><div><strong>${esc(p.name)}</strong><small>${p.budget} jeton · ${p.cards.length}/${g.settings.slots} kart</small></div><span>${p.id===g.turnId?'İlk teklif':p.id===g.leaderId?'Önde':g.status==='bidding'&&!g.activeIds.includes(p.id)?p.cards.length===g.settings.slots?'Dolu':'Bu kartta yok':canBid(g,p.id)?'Artırabilir':''}</span></div>`).join('')}</div>`;}
 function display(room,c){
  const g=room.game,s=room.series,sold=g.status==='sold'||g.status==='finished',countdown=g.status==='countdown',person=g.players.find(p=>p.id===g.turnId),leader=g.players.find(p=>p.id===g.leaderId),events=(g.activity||[]).filter(a=>a.cardId===g.current?.id).slice(0,4);
  if(s?.phase==='voting')return `<section class="tv-interlude"><span class="tv-kicker">Sonraki turu seçiyoruz</span><h1>Telefonundan oy ver.</h1><div class="tv-vote-cards">${s.vote.candidates.map(id=>{const category=c(id),votes=Object.values(s.vote.votes).filter(v=>v===id).length;return `<article><h2>${esc(category.name)}</h2><strong>${votes} oy</strong></article>`;}).join('')}</div><p data-vote-timer>İlk oy bekleniyor</p></section>${players(g)}`;
  if(g.status==='finished')return `<section class="tv-round-end"><span class="tv-kicker">${s?.phase==='finished'?'Seri tamamlandı':'Tur tamamlandı'}</span><h1>${s?.phase==='review'?'Son söz sizde.':'Kadrolar hazır.'}</h1>${g.lastSale?`<p>Son kart: ${esc(g.lastSale.name)}, ${esc(g.lastSale.card.name)} · ${g.lastSale.card.paid} jeton</p>`:''}<div class="tv-final-teams">${g.players.map(p=>`<article><h2>${esc(p.name)} ${p.total!==null?`<small>${p.total} puan</small>`:''}</h2>${p.cards.map(card=>`<div>${photo(card,'tv-final-photo')}<span>${esc(card.name)}</span><b>${card.paid} j</b></div>`).join('')}</article>`).join('')}</div>${s?seriesUI.board(s):'<p>Kazananı birlikte değerlendirin. Sonuçları oda sahibinin telefonundan kopyalayabilirsiniz.</p>'}<p class="tv-host-note">${s?.phase==='review'?'Oda sahibi sıralamayı telefonundan kaydetsin.':s?.phase==='finished'?'Yeni seriyi oda sahibi telefonundan kurabilir.':'Sıradaki turu oda sahibi telefonundan başlatır.'}</p></section>`;
  return `<section class="tv-auction ${sold?'is-sold':''}"><div class="tv-stage">${countdown?`<div class="tv-reveal"><span class="tv-kicker">Sıradaki kart geliyor</span><strong data-reveal-number>3</strong><p>Hazır mısınız?</p><small>Kart ${g.index+2} / ${g.totalCards}</small></div>`:`<div class="tv-card-meta"><span>${esc(c(g.settings.categoryId).name)}</span><span>Kart ${g.index+1} / ${g.totalCards}</span></div><article class="tv-card">${photo(g.current,'tv-photo',true)}<div><span class="tv-kicker">${esc(g.current.universe||c(g.settings.categoryId).group)}</span><h1>${esc(g.current.name)}</h1><p>${esc(cardInfo(g.current).text)}</p></div></article>`}</div><aside class="tv-bid-board">${countdown?'<div class="tv-waiting"><span class="tv-kicker">Yeni bir fırsat</span><h2>Gözünüz ekranda,<br>parmağınız düğmede.</h2><p>Kart açılınca ilk teklif sırası görünecek.</p></div>':sold?`<div class="tv-sold"><span class="tv-kicker">Satıldı ✓</span><h2>${esc(g.lastSale.name)} aldı!</h2><div class="tv-sale-price"><strong>${g.lastSale.card.paid}</strong><span>jetona aldı</span></div><p><b>${g.lastSale.remainingBudget}</b> jetonu kaldı</p>${g.settings.pricePerformance?stars(g.lastSale.card.deal):''}<div class="tv-next-wait">Sıradaki kart birazdan <b data-next-number></b></div></div>`:`<div class="tv-live-bid"><span class="tv-kicker">${leader?'En yüksek teklif':'Açılış fiyatı'}</span><div class="tv-sale-price"><strong>${g.price||1}</strong><span>jeton</span></div><h2>${leader?esc(leader.name)+' teklif verdi.':'İlk teklif '+esc(person?.name)+'’den.'}</h2><p>${leader?'Artıran var mı?':'Telefonundaki düğmeyle başlat.'}</p>${timerUI(g)}<div class="tv-turn"><small>${g.price===0?'İlk teklif':'Serbest artırma'}</small><strong>${g.price===0?esc(person?.name):'İsteyen artırabilir'}</strong><span>${g.price===0?'1 jetonla başlat':`Sıra beklemeden ${g.price+1} jeton ver`}</span></div></div>`}${!countdown?`<div class="tv-events"><h3>Son teklifler</h3>${events.length?events.map(a=>`<p><b>${esc(a.name)}</b><span>${a.type==='bid'?a.amount+' jeton':a.type==='joker'?'Kartı değiştirdi':'Çekildi'}</span></p>`).join(''):'<p>İlk teklif bekleniyor.</p>'}</div>`:''}</aside></section>${players(g)}`;
 }
 function lobby(room,link){return `<section class="tv-interlude tv-lobby"><div class="tv-lobby-layout"><div><span class="tv-kicker">Oda ${esc(room.code)} · TV ekranı hazır</span><h1>Masaya hoş geldiniz.</h1><p>Telefonlarınızdan odaya katılın.<br>Oda sahibi başlatınca ilk kart burada açılacak.</p><div class="tv-lobby-players">${room.members.map(m=>`<span>${esc(m.name)}${m.host?' · Oda sahibi':''}</span>`).join('')}</div></div>${joinQR(link)}</div></section>`;}
 return {controller,display,lobby};
}
